begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
create temp table queue_test_ids(label text, business_id uuid, location_id uuid);
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_a"}', true);
insert into queue_test_ids(label,business_id) values ('a', public.onboard_business('Clinic A','healthcare','GH','Africa/Accra','Main','Accra'));
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_b"}', true);
insert into queue_test_ids(label,business_id) values ('b', public.onboard_business('Clinic B','healthcare','GH','Africa/Accra','Main','Accra'));
update queue_test_ids t set location_id = (select id from locations where business_id = t.business_id);
grant select on queue_test_ids to authenticated, anon;
insert into business_members(business_id,clerk_user_id,role) select business_id,'queue_admin','admin' from queue_test_ids where label='a';
insert into business_members(business_id,clerk_user_id,role) select business_id,'queue_staff','staff' from queue_test_ids where label='a';
set local role anon;
select set_config('request.jwt.claims', '{"role":"anon","sub":"anonymous"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, '42501', null, 'anonymous creation denied');
select throws_ok($$select public.update_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,(select location_id from queue_test_ids where label = 'a'),'Renamed consultation',null,600,2,false,false)$$, '42501', null, 'anonymous editing denied');
select throws_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,'paused')$$, '42501', null, 'anonymous status change denied');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_staff"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, '42501', null, 'staff cannot create queues');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"outsider"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, '42501', null, 'outsider cannot create in another tenant');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_a"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'b'),(select location_id from queue_test_ids where label = 'b'),' Consultation ',' Description ',300,3,true,false)$$, '42501', null, 'owner cannot create in another tenant');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'b'),' Consultation ',' Description ',300,3,true,false)$$, '22023', null, 'cross-tenant location rejected');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' ',' Description ',300,3,true,false)$$, '22023', null, 'blank name rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),repeat('a',161),' Description ',300,3,true,false)$$, '22023', null, 'oversized name rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',repeat('x',2001),300,3,true,false)$$, '22023', null, 'oversized description rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',0,3,true,false)$$, '22023', null, 'zero service time rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',86401,3,true,false)$$, '22023', null, 'oversized service time rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,-1,true,false)$$, '22023', null, 'negative threshold rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,101,true,false)$$, '22023', null, 'oversized threshold rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,false,true)$$, '22023', null, 'inconsistent phone settings rejected by direct RPC');
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,null,false)$$, '22023', null, 'null phone setting rejected by direct RPC');
reset role;
update locations set is_active=false where id=(select location_id from queue_test_ids where label = 'a');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_a"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, '22023', null, 'inactive location rejected');
reset role;
update locations set is_active=true where id=(select location_id from queue_test_ids where label = 'a');
-- Queue shape/slug tests use the paid capacity; free limits are tested separately.
update businesses set subscription_tier='BUSINESS' where id=(select business_id from queue_test_ids where label='a');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_a"}', true);
select lives_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, 'owner creates queue');
select lives_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),'Retry name',' Description ',300,3,true,false)$$, 'retry returns same queue');
select is((select count(*) from queues),1::bigint,'retry creates only one queue');
select is((select name from queues),'Consultation','name trimmed and retry cannot overwrite it');
select is((select description from queues),'Description','description trimmed');
select is((select status::text from queues),'open','queue initially open');
select is((select revision from queues),1,'new queue revision is one');
select is((select count(*) from business_events where type='queue_created'),1::bigint,'creation audited once');
select is((select actor_user_id from business_events where type='queue_created'),'queue_owner_a','audit uses verified subject');
select ok((select slug not like '%' || replace(id::text,'-','') || '%' from queues),'slug uses a separate random suffix');
reset role;
create temp table original_queue_slug as select slug from queues;
grant select on original_queue_slug to authenticated;
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_b"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'b'),(select location_id from queue_test_ids where label = 'b'),' Consultation ',' Description ',300,3,true,false)$$, '42501', null, 'cannot replay another tenant queue ID');
select throws_ok($$select public.update_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'b'),1,(select location_id from queue_test_ids where label = 'b'),'Renamed consultation',null,600,2,false,false)$$, '42501', null, 'cannot edit another tenant queue');
select throws_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'b'),1,'paused')$$, '42501', null, 'cannot change another tenant status');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_staff"}', true);
select throws_ok($$select public.update_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,(select location_id from queue_test_ids where label = 'a'),'Renamed consultation',null,600,2,false,false)$$, '42501', null, 'staff cannot edit queue settings');
select throws_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,'paused')$$, '42501', null, 'staff cannot use management status RPC');
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_admin"}', true);
select lives_ok($$select public.update_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,(select location_id from queue_test_ids where label = 'a'),'Renamed consultation',null,600,2,false,false)$$, 'admin edits settings');
select is((select slug from queues),(select slug from original_queue_slug),'renaming preserves public slug');
select is((select revision from queues),2,'edit advances revision');
select throws_ok($$select public.update_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,(select location_id from queue_test_ids where label = 'a'),'Renamed consultation',null,600,2,false,false)$$, '40001', null, 'stale edit rejected');
select throws_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),1,'paused')$$, '40001', null, 'stale status change rejected');
select throws_ok($$select public.update_queue('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),2,(select location_id from queue_test_ids where label = 'b'),'Renamed consultation',null,600,2,false,false)$$, '22023', null, 'edit cannot move queue across tenants');
select lives_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),2,'paused')$$, 'pause succeeds');
select lives_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),3,'paused')$$, 'same status is a no-op');
select is((select revision from queues),3,'no-op does not advance revision');
select lives_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),3,'open')$$, 'resume succeeds');
select lives_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),4,'closed')$$, 'close succeeds');
select lives_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),5,'open')$$, 'reopen succeeds');
select throws_ok($$select public.set_queue_status('10000000-0000-4000-8000-000000000001',(select business_id from queue_test_ids where label = 'a'),6,null)$$, '22023', null, 'null status rejected');
select is((select count(*) from business_events where type='queue_status_changed'),4::bigint,'only real transitions produce audit events');
select is((select count(*) from business_events where type='queue_updated'),1::bigint,'only successful settings edits audited');
select throws_ok($$update queues set name='Direct write'$$, '42501', null, 'direct table writes remain blocked');
select lives_ok($$select public.create_queue('10000000-0000-4000-8000-000000000002',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),'診療所',' Description ',300,3,true,false)$$, 'non-Latin name creates valid slug');
select ok((select slug ~ '^queue-[a-f0-9]{32}$' from queues where id='10000000-0000-4000-8000-000000000002'),'non-Latin name uses fallback slug');
select lives_ok($$select public.create_queue('10000000-0000-4000-8000-000000000003',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),repeat('a',59)||' b',' Description ',300,3,true,false)$$, 'truncated slug does not contain double hyphen');
select lives_ok($$select public.create_queue('10000000-0000-4000-8000-000000000004',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, 'duplicate queue names allowed');
select is((select count(distinct slug) from queues),4::bigint,'all public slugs unique');
reset role;
create function pg_temp.fail_queue_audit() returns trigger language plpgsql as $$
begin
  if new.type = 'queue_created' then raise exception 'Simulated audit failure'; end if;
  return new;
end;
$$;
create trigger queue_audit_test_failure before insert on business_events for each row execute function pg_temp.fail_queue_audit();
set local role authenticated;
select set_config('request.jwt.claims', '{"role":"authenticated","sub":"queue_owner_a"}', true);
select throws_ok($$select public.create_queue('10000000-0000-4000-8000-000000000005',(select business_id from queue_test_ids where label = 'a'),(select location_id from queue_test_ids where label = 'a'),' Consultation ',' Description ',300,3,true,false)$$, 'P0001', null, 'audit failure rolls back creation');
select is((select count(*) from queues),4::bigint,'failed audit leaves no orphan queue');
reset role;
set constraints all immediate;
select * from finish();
rollback;
